export const d5Update="Fictional explicit D5 selections: for Synthetic product A choose Cannabinoid hemp products; for Synthetic product B choose Other under Other Product Types. Keep reporting product categories, drug labels and cosmetic choices unchanged.";
export const d5Correction="Correction for Synthetic product B only: explicitly select both Other and Cannabinoid hemp products in D5 Other Product Types; both classifications were supplied, label review pending. Keep product A and all other facts unchanged.";
export const d5Context="both classifications were supplied, label review pending";
export function d5Case(){let c=productCapacityCase();c=setContextFact(c,"product:product-apixaban:medicationType",{kind:"known",value:["brand","otc"]});c=setContextFact(c,"product:product-apixaban:cosmeticUse",{kind:"known",value:"retail"});return setContextFact(c,"product:product-naproxen:cosmeticUse",{kind:"known",value:"professional-use-only"});}
