export function d5Conflict(){const c=setContextFact(d5Case(),"product:product-apixaban:otherProductTypes",{kind:"known",value:["cannabinoid-hemp"],qualifier:"first record classification"}),source=contextSource("d5-other-dispute","Fictional second record explicitly selects Other in D5; classification unresolved.");const pending=applyCaseCommand(c,{type:"attach-grounded-proposals",commandId:"d5-pending",expectedRevision:c.revision,products:[],sources:[source],proposals:[{proposalId:"d5-alternative",groupId:"d5-dispute",intent:"alternative",target:{entity:"product",entityId:"product-apixaban",field:"otherProductTypes"},value:{kind:"known",value:["other"],qualifier:"second record classification"},sourceIds:[source.id]}]}).case;return{pending,accepted:applyCaseCommand(pending,{type:"review-proposal-groups",commandId:"d5-accept",expectedRevision:pending.revision,decisions:[{groupId:"d5-dispute",action:"accept"}]}).case};}
